function driveIdFromRef(ref){const match=/^drive:\/\/([^/?#]+)/i.exec(String(ref||''));return match?.[1]||''}
function cleanImageRef(value){if(typeof value!=='string')return '';const src=value.trim();if(!src||/^(?:data:image\/|blob:)/i.test(src))return '';if(driveIdFromRef(src))return src;try{const url=new URL(src);return ['http:','https:'].includes(url.protocol)?src:''}catch{return ''}}
function sanitizeVolatileValue(value){if(typeof value==='string')return /^(?:data:image\/|blob:)/i.test(value)?'':value;if(Array.isArray(value))return value.map(sanitizeVolatileValue);if(value&&typeof value==='object'){const out={};for(const [key,item] of Object.entries(value)){if(typeof item==='function'||key==='file')continue;out[key]=sanitizeVolatileValue(item)}return out}return value}
function cleanEntryImages(entry){
  const out={...entry};
  const driveFiles=Array.isArray(out.driveFiles)?out.driveFiles.filter(file=>file&&file.id).map(file=>({...file,index:Math.max(0,Number(file.index)||0)})):[];
  const hasImages=Array.isArray(out.images);
  const hasUsefulImageArray=hasImages&&(out.images.some(Boolean)||driveFiles.length>0);
  const original=hasUsefulImageArray?out.images:(out.image?[out.image]:[]);
  const count=Math.max(original.length,driveFiles.reduce((max,file)=>Math.max(max,file.index+1),0));
  const mapped=Array.from({length:count},(_,index)=>{
    const driveFile=driveFiles.find(file=>file.index===index);
    const src=driveFile?.id?`${DRIVE_REF_PREFIX}${driveFile.id}`:cleanImageRef(original[index]||'');
    return {src,driveFile};
  }).filter(item=>item.src);
  out.driveFiles=mapped.map((item,index)=>item.driveFile?({...item.driveFile,index}):null).filter(Boolean);
  if(hasImages||driveFiles.length){out.images=mapped.map(item=>item.src);out.image=out.images[0]||''}
  else out.image=mapped[0]?.src||'';
  return sanitizeVolatileValue(out);
}
function normalizeDb(d){
  const merged={...structuredClone(seed),...d,
    products:(Array.isArray(d.products)?d.products:structuredClone(seed.products)).map(cleanEntryImages),
    users:Array.isArray(d.users)?d.users:structuredClone(seed.users),
    orders:Array.isArray(d.orders)?d.orders:structuredClone(seed.orders),
    drafts:(Array.isArray(d.drafts)?d.drafts:[]).map(cleanEntryImages),
    feeds:Array.isArray(d.feeds)?d.feeds.map(sanitizeVolatileValue):[],
    weights:{...seed.weights,...(d.weights||{})}};
  return sanitizeVolatileValue(merged);
}
function loadDb(){
  const remote=window.MERCHANT_DESK_INITIAL_STATE;
  if(remote&&typeof remote==='object')return normalizeDb(remote);
  try{const raw=localStorage.getItem(LOCAL_STORE_KEY);if(raw)return normalizeDb(JSON.parse(raw));}catch(e){console.warn('User-scoped local cache could not be read; starting from demo data.',e)}
  return normalizeDb(structuredClone(seed))
}
function persist(){
  try{
    db._updatedAt=new Date().toISOString();
    const snapshot=sanitizeVolatileValue(structuredClone(db));
    localStorage.setItem(LOCAL_STORE_KEY,JSON.stringify(snapshot));
    window.dispatchEvent(new CustomEvent('merchantdesk:state-change',{detail:{state:snapshot,userId:USER_ID}}));
    return true;
  }catch(e){console.error('Local backup failed',e);toast('Browser storage is unavailable. Product photo files are stored in Drive, not browser storage.');return false}
}
const $=id=>document.getElementById(id);
