function getStoredImage(p,index=0){const items=Array.isArray(p?.images)&&p.images.some(Boolean)?p.images:(p?.image?[p.image]:[]);const id=p?.driveFiles?.find(file=>Number(file.index)===index)?.id||driveIdFromRef(items[index]||'');return id?`${DRIVE_REF_PREFIX}${id}`:cleanImageRef(items[index]||'')}
function resolveImageSource(src,driveFile=null){const id=driveFile?.id||driveIdFromRef(src);if(id)return window.MerchantDrive?.getCachedImageUrl(id)||'';return cleanImageRef(src)}
const getImage=p=>resolveImageSource(getStoredImage(p,0),p?.driveFiles?.find(file=>Number(file.index)===0));
function formImageDriveId(im){return im?.drive?.id||driveIdFromRef(im?.src||'')}
function storedFormImageRef(im){const id=formImageDriveId(im);return id?`${DRIVE_REF_PREFIX}${id}`:cleanImageRef(im?.src||'')}
function collectDriveImageIds(){const ids=[];const add=entry=>{const images=Array.isArray(entry?.images)&&entry.images.some(Boolean)?entry.images:(entry?.image?[entry.image]:[]);images.forEach((src,index)=>{const id=entry?.driveFiles?.find(file=>Number(file.index)===index)?.id||driveIdFromRef(src||'');if(id)ids.push(id)})};db.products.forEach(add);db.drafts.forEach(add);return [...new Set(ids)]}
async function hydrateDriveImages(){if(!window.MerchantDrive?.isDriveReady())return;const result=await window.MerchantDrive.cacheImages(collectDriveImageIds());renderAll();if($('productModalBackdrop')?.classList.contains('open'))renderImagePreviews();if(result.failures.length)console.warn('Some Drive product images could not be loaded.',result.failures)}
